// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 1000 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        vm.prank(actor);
        c.withdrawAll();

        // After a successful withdrawAll the actor's credit is zero, so a second
        // withdrawAll is a no-op and must succeed. The buggy version restores
        // credit to the old amount, so the second call underflows `balance` and reverts.
        bool okSecond;
        vm.prank(actor);
        try c.withdrawAll() {
            okSecond = true;
        } catch {
            okSecond = false;
        }
        assertTrue(okSecond, "second withdrawAll must be a successful no-op");
    }
}
